      'subq_nonce_ground_truth_verification',
      'subq_nonce_demo_execution',
      'subq_nonce_live_ground_truth_integration',
      'subq_nonce_role_separation',
      'subq_nonce_merge_step3_tsr',
      'subq_nonce_skill_interface',
      'subq_nonce_skill_reeval',
      'subq_nonce_skill_revision_and_schema_reject',
      'subq_supersession_and_gap_analysis'
    ]
  }
];

const definedIds = new Set(subquestions.map(q => q.subquestion_id));
const invalidDeps = [];
for (const q of subquestions) {
  for (const dep of q.synthesis_dependencies) {
    if (!definedIds.has(dep)) invalidDeps.push(`${q.subquestion_id} -> ${dep}`);
  }
}

return {
  subquestion_count: subquestions.length,
  invalid_dependencies: invalidDeps,
  max_context_bytes: Math.max(...subquestions.map(q => q.context_files.reduce((s, p) => s + (sizeMap[p] || 0), 0))),
  all_valid_paths: subquestions.every(q => q.context_files.every(f => allPaths.has(f)))
};
